use nori_core::types::FileKind;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// A file identified by the crawler as eligible for indexing.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Candidate {
    pub path: String,
    pub kind: FileKind,
    pub size: i64,
    pub mtime: f64,
    pub inode: u64,
    pub device: u64,
}

/// Statistics and candidates generated by a directory crawl run.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct CrawlReport {
    pub candidates: Vec<Candidate>,
    /// Reasons files were skipped -> file count.
    pub skipped: HashMap<String, usize>,
    /// Reasons directories were not traversed -> folder count.
    pub skipped_folders: HashMap<String, usize>,
    /// Machine-named dataset directories skipped -> file count.
    pub datasets: HashMap<String, usize>,
}
